import type { ProjectListItem } from '~/types/projects/list/item';
import type {
  GetProjectDetailsResponse,
  ProjectDetailsForAdmin,
  ProjectListItemForAdmin,
  ProjectListItemForManager,
  SignatureProjectGoal,
  CanvassingProjectGoal,
  SignatureProjectPricing,
  CanvassingProjectPricing,
  CanvassingUpcomingCanvasserPricing,
  CanvassingUpcomingManagerPricing,
  SignatureUpcomingCanvasserPricing,
  SignatureUpcomingManagerPricing,
  CanvassingSelectorPricing,
  SignatureSelectorPricing,
  SignatureProjectRegion,
  SignatureProjectStatistics,
  CanvassingProjectDetailsStatistics,
  ProjectGeneralInfoRegion,
} from '~/client';

export function isAdminProjectDetails(details: GetProjectDetailsResponse): details is ProjectDetailsForAdmin {
  return 'pricing' in details && 'payments_enabled' in details.pricing;
}

export function isProjectListItemForManagerOrAdmin(
  item: ProjectListItem
): item is ProjectListItemForManager | ProjectListItemForAdmin {
  return 'client_name' in item;
}

export function isSignatureProjectGoal(
  goal: SignatureProjectGoal | CanvassingProjectGoal
): goal is SignatureProjectGoal {
  return 'signatures_goal' in goal;
}

export function isCanvassingProjectGoal(
  goal: SignatureProjectGoal | CanvassingProjectGoal
): goal is CanvassingProjectGoal {
  return 'total_voters' in goal;
}

export function isSignaturePricing(
  pricing: SignatureProjectPricing | CanvassingProjectPricing
): pricing is SignatureProjectPricing {
  return 'for_canvasser_per_signature' in pricing;
}

export function isCanvassingPricing(
  pricing: SignatureProjectPricing | CanvassingProjectPricing
): pricing is CanvassingProjectPricing {
  return 'for_canvasser_per_hour' in pricing;
}

export function isUpcomingCanvassingProjectPricing(
  pricing:
    | SignatureUpcomingManagerPricing
    | SignatureUpcomingCanvasserPricing
    | CanvassingUpcomingCanvasserPricing
    | CanvassingUpcomingManagerPricing
): pricing is CanvassingUpcomingManagerPricing | CanvassingUpcomingCanvasserPricing {
  return 'for_canvasser_per_hour' in pricing;
}

export function isUpcomingSignatureProjectPricing(
  pricing:
    | SignatureUpcomingManagerPricing
    | SignatureUpcomingCanvasserPricing
    | CanvassingUpcomingCanvasserPricing
    | CanvassingUpcomingManagerPricing
): pricing is SignatureUpcomingManagerPricing | SignatureUpcomingCanvasserPricing {
  return 'for_canvasser_per_signature' in pricing;
}

export function isUpcomingProjectPricingForManagerOrAdmin(
  pricing:
    | SignatureUpcomingManagerPricing
    | SignatureUpcomingCanvasserPricing
    | CanvassingUpcomingCanvasserPricing
    | CanvassingUpcomingManagerPricing
): pricing is SignatureUpcomingManagerPricing | CanvassingUpcomingManagerPricing {
  return 'qrf_for_canvasser_per_signature' in pricing || 'qrf_for_canvasser_per_hour' in pricing;
}

export function isUpcomingSignaturePricingForManagerOrAdmin(
  pricing:
    | SignatureUpcomingManagerPricing
    | SignatureUpcomingCanvasserPricing
    | CanvassingUpcomingCanvasserPricing
    | CanvassingUpcomingManagerPricing
): pricing is SignatureUpcomingManagerPricing {
  return 'qrf_for_canvasser_per_signature' in pricing;
}

export function isUpcomingCanvassingPricingForManagerOrAdmin(
  pricing:
    | SignatureUpcomingManagerPricing
    | SignatureUpcomingCanvasserPricing
    | CanvassingUpcomingCanvasserPricing
    | CanvassingUpcomingManagerPricing
): pricing is CanvassingUpcomingManagerPricing {
  return 'qrf_for_canvasser_per_hour' in pricing;
}

export function isSignaturePayment(
  payment: SignatureSelectorPricing | CanvassingSelectorPricing | SignatureProjectPricing | CanvassingProjectPricing
): payment is SignatureSelectorPricing | SignatureProjectPricing {
  return 'for_canvasser_per_signature' in payment;
}

export function isCanvassingPayment(
  payment: SignatureSelectorPricing | CanvassingSelectorPricing | SignatureProjectPricing | CanvassingProjectPricing
): payment is CanvassingSelectorPricing | CanvassingProjectPricing {
  return 'for_canvasser_per_hour' in payment;
}

export function isSignatureRegion(
  region: SignatureProjectRegion | ProjectGeneralInfoRegion
): region is SignatureProjectRegion {
  return 'signatures_goal' in region;
}

export function isSignatureProjectStatistics(
  project: SignatureProjectStatistics | CanvassingProjectDetailsStatistics
): project is SignatureProjectStatistics {
  return 'collected_signatures' in project;
}

export function isCanvassingProjectStatistics(
  project: SignatureProjectStatistics | CanvassingProjectDetailsStatistics
): project is CanvassingProjectDetailsStatistics {
  return 'canvassed_voters' in project;
}

type IncreasedPayRatePayment =
  | SignatureSelectorPricing
  | CanvassingSelectorPricing
  | SignatureProjectPricing
  | CanvassingProjectPricing
  | SignatureUpcomingManagerPricing
  | SignatureUpcomingCanvasserPricing
  | CanvassingUpcomingManagerPricing
  | CanvassingUpcomingCanvasserPricing;

export function isIncreasedPayRateApplicable(
  payment: IncreasedPayRatePayment,
  existingIncreasedPayRate?: number | null
): boolean {
  if (!('for_canvasser_per_hour' in payment)) return false;
  return payment.increased_pay_rate_enabled || existingIncreasedPayRate != null;
}
